import {photoMemorialDate} from './photo-sample-view.js';
import {PLAYER_AVATAR,playerOutfit} from './player-style.js';
import {durationLabel} from './time-label.js';
import {LAND_PALETTES,landPalette} from './terrain-palettes.js';
import {legacyRecoveryEligible} from './navigation.js';
import {isBuilt,constructionProgress,workRemaining} from './construction.js';
import {getBlueprint,ACTIVE_BUILDING_SAMPLES,isActiveBuildingSample,RELOCATION_PRICE,DEMOLITION_PRICE} from './blueprints.js';
import {BASIC_VARIETIES,OFFICIAL_VARIETIES,allCatalogueVarieties,CREATIVE_SAMPLES,DEMO_GARDENS,BUILDINGS} from './catalogue.js';
import {availableBasics,getVariety,sameVariety,canBuySeed,isMature,dayKey,reclaimRefund,compatibleRemixSamples,reusablePersonalVariety} from './state.js';
import {exhibitHint} from './exhibit-controls.js';
import {footprintOf,plantAtTile,buildingAtTile} from './footprints.js';
import {icon} from './icons.js';
import {controlHint} from './plant-controls.js';
export const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,text,cls='secondary',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const avatarPortrait=(id,name)=>`<canvas class="avatar-portrait" data-avatar-portrait="${esc(id)}" role="img" aria-label="${esc(name)}"></canvas>`;
const art=(key,cls='')=>`<canvas class="${cls}" data-art="${esc(key)}" aria-hidden="true"></canvas>`;
export const knownVarieties=s=>[...new Map([...Object.values(s.varieties).map(v=>getVariety(s,v.id)).filter(v=>v.kind!=='basic'||availableBasics(s).some(x=>x.id===v.id)||(s.inventory[v.id]??0)>0||s.discovered.includes(v.id)),...availableBasics(s).filter(v=>!Object.hasOwn(s.varieties,v.id))].map(v=>[v.id,v])).values()];
export const revealed=(s,v)=>v.kind==='basic'||s.discovered.includes(v.id)||[...s.plants,...(s.plantBag??[])].some(p=>p.varietyId===v.id&&isMature(p,Date.now()));
const sealed=()=>`<span class="unknown-seed">${icon('seed')}</span>`;
const workContext=(item,time,title)=>`<div class="context-head"><div class="worksite-mark">${icon('hammer')}</div><div><h3>${esc(title)} · 建设中</h3><p>还需 ${workRemaining(item,time)} 秒 · 进度自动保留</p></div></div><div class="progress-bar"><i style="width:${Math.floor(constructionProgress(item,time)*100)}%"></i></div><p class="context-detail">完成后就能使用。等待不会再次花费。</p>`;
const coin=n=>`${icon('coin')} ${n}`;
// Compact card actions wrap only between the action and the complete coin amount.
const compactPrice=(label,n)=>`<span class="price-action-label">${esc(label)}</span> <span class="price-amount">${icon('coin')}<span class="price-value">${n}</span></span>`;
const header=(title,badge='')=>`<header class="tray-heading"><h2>${title}${badge?`<small>${badge}</small>`:''}</h2>${button('close-panel',icon('close'),'close-button','aria-label="关闭面板"')}</header>`;
const wrap=(title,body,badge='',rail='',footer='')=>`${header(title,badge)}<div class="tray-content">${body}</div>${rail}${footer}`;
const creationRail=(action,label)=>`<footer class="panel-action-rail">${button(action,`＋ ${label} · 1 水晶`,'primary purple full')}</footer>`;
export function renderHUD(s,avatars,saveLabel='慢慢种，轻轻玩'){
 const name='苏贝壳';
 return `<div class="identity-group">${button('profile',`${avatarPortrait(PLAYER_AVATAR,name)}<span><strong>贝壳的花园</strong><small id="save-state">${esc(saveLabel)}</small></span>`,'identity','aria-label="苏贝壳的衣橱与说明"')}${button('panel-invite',icon('invite'),'invite-icon','aria-label="邀请好友" title="邀请好友"')}</div><div class="wallets">${button('coins',`${icon('coin')}<b>${s.coins}</b>`,'wallet coins','title="双击补充100演示金币" aria-label="金币 '+s.coins+'，双击补充100演示金币"')}${button('crystals',`${icon('crystal')}<b>${s.crystals}</b><span class="wallet-plus">+</span>`,'wallet crystals','aria-label="灵感水晶 '+s.crystals+'"')}</div>`;
}
export function renderDock(active){return [['bag','seed','种植'],['build','hammer','建造'],['visit','visit','串门']].map(([id,i,label])=>button(`panel-${id}`,`${icon(i)}<span>${label}</span>`,id==='create'?'create-button':'',`aria-label="${label}" aria-expanded="${active===id}"`)).join('');}
export function renderTools(s){return button('mute',icon(s.settings.muted?'mute':'sound'),'tool-button',`aria-label="${s.settings.muted?'开启':'关闭'}声音" aria-pressed="${s.settings.muted}"`)+button('recenter',icon('center'),'tool-button','aria-label="回到小岛中心"')+button('zoom-in',icon('plus'),'tool-button','aria-label="放大花园"')+button('zoom-out',icon('minus'),'tool-button','aria-label="缩小花园"');}
function seedCard(s,v,{shop=false}={}){
 const seedButton=(action,text,cls,attrs='')=>button(action,text,cls,`${attrs} data-seed-control="${action}"`);
 const count=s.inventory[v.id]??0,isKnown=revealed(s,v),image=isKnown?art(v.artKey):sealed(),source=v.authorId===s.uid?'我的创作':v.kind==='basic'?'原生种子':`原作 ${esc(v.authorName)}`;
 const content=`${count>0?`<span class="count-badge">×${count}</span>`:''}${!isKnown?'<span class="new-tag">待揭晓</span>':''}${image}<b>${esc(isKnown?v.name:'一颗灵感新种子')}</b><small>${shop?`${durationLabel(v.growMs)}长大 · 售${v.salePrice}币`:source}</small>`;
 const detail=!shop?seedButton('detail','详情 · 改造','link-button seed-detail',`data-id="${esc(v.id)}"`):'';
 if(!shop&&count>0)return `<div class="item-card seed-card has-stock${!isKnown?' is-new':''}" data-seed-id="${esc(v.id)}">${seedButton('choose-seed',`${content}<span class="card-buy seed-plant-label">种下 ${icon('seed')}</span>`,'seed-main',`data-id="${esc(v.id)}" aria-label="种下${esc(isKnown?v.name:'灵感新种子')}，现有${count}颗"`)}${canBuySeed(s,v.id)?seedButton('buy-seed',compactPrice('+1',v.seedPrice),'seed-repeat price-action',`data-id="${esc(v.id)}" ${s.coins<v.seedPrice?'disabled':''} aria-label="再买一颗${esc(isKnown?v.name:'灵感新种子')}，${v.seedPrice}金币"`):''}${detail}</div>`;
 const locked=v.kind==='basic'&&!canBuySeed(s,v.id),sourceGarden=DEMO_GARDENS.find(g=>g.plants.some(p=>p.varietyId===v.id));
 const action=locked?seedButton('panel-shop',`再卖出 ${Math.max(0,v.unlockSales-s.sales)} 株解锁`,'card-buy',`disabled aria-label="累计卖出${v.unlockSales}株解锁，还差${Math.max(0,v.unlockSales-s.sales)}株"`):shop?seedButton('buy-seed',coin(v.seedPrice),'card-buy',`data-id="${esc(v.id)}" ${s.coins<v.seedPrice?'disabled':''} aria-label="花${v.seedPrice}金币购买${esc(v.name)}种子"`):canBuySeed(s,v.id)?seedButton('buy-seed',compactPrice('购买',v.seedPrice),'card-buy price-action',`data-id="${esc(v.id)}" ${s.coins<v.seedPrice?'disabled':''} aria-label="购买${esc(isKnown?v.name:'灵感新种子')}，${v.seedPrice}金币"`):seedButton('visit-seed-source',sourceGarden?'去来源花园':'当前暂未展出','card-buy',`data-id="${esc(v.id)}" ${sourceGarden?'':'disabled'}`);
 return `<div class="item-card${!shop?' seed-card no-stock':''}${!isKnown?' is-new':''}" data-seed-id="${esc(v.id)}">${content}${!shop?`<small class="stock-empty">${locked?'尚未解锁购买':canBuySeed(s,v.id)?'库存 0 · 可直接购买':sourceGarden?'库存 0 · 可去来源花园领取':'旧版收藏 · 当前暂未展出'}</small>`:''}${action}${locked&&DEMO_GARDENS.some(g=>g.plants.some(p=>p.varietyId===v.id))?seedButton('visit-seed-source','去来源花园领取','link-button',`data-id="${esc(v.id)}"`):''}${detail}</div>`;
}
function shopPanel(s){
 const bases=availableBasics(s),creations=Object.values(s.varieties).filter(v=>v.authorId===s.uid),next=OFFICIAL_VARIETIES.find(v=>v.unlockSales>s.sales&&!availableBasics(s).some(a=>a.id===v.id));
 return wrap('种子铺',`<p class="panel-subtitle">金币买种子。我的创作品种可以重复买，<b>不再用水晶</b>。</p><div class="item-grid">${[...bases,...creations].map(v=>seedCard(s,v,{shop:true})).join('')}</div>${next?`<p class="unlock-note">${icon('leaf')}再卖出 ${next.unlockSales-s.sales} 株成熟植物，认识一个新原生品种。</p>`:'<p class="unlock-note">8 个原生品种都认识啦，让花园长成你的样子。</p>'}<p class="help-note">串门种子从示范花园领取。水晶用完，也能继续种地。</p>`);
}
const bagTabs=(s,tab)=>`<div class="tabs">${['seeds','plants'].map(id=>button(`bag-tab-${id}`,{seeds:'种子',plants:`收获 · ${(s.plantBag??[]).length}`}[id],tab===id?'active':'')).join('')}</div>`;
function seedList(s,u){
 const owned=knownVarieties(s).sort((a,b)=>Number((s.inventory[b.id]??0)>0)-Number((s.inventory[a.id]??0)>0)),next=OFFICIAL_VARIETIES.find(v=>v.unlockSales>s.sales&&!availableBasics(s).some(a=>a.id===v.id));
 return `<div class="item-grid seed-grid">${owned.map(v=>seedCard(s,v)).join('')}</div>${next?`<p class="unlock-note">再卖出 ${next.unlockSales-s.sales} 株成熟植物，认识一个新原生品种。</p>`:''}`;
}
export const renderSeedPurchaseContent=(s,u)=>bagTabs(s,'seeds')+seedList(s,u);
export function purchaseSummary(s,id){const v=getVariety(s,id);if(!v||!canBuySeed(s,id))return null;const count=s.inventory[id]??0;return {id,name:revealed(s,v)?v.name:'灵感新种子',count,price:v.seedPrice,canRepeat:s.coins>=v.seedPrice&&count<10000000};}
function bagPanel(s,u){
 const tab=u.bagTab==='plants'?'plants':'seeds';let body=bagTabs(s,tab);
 if(u.detailId){const v=getVariety(s,u.detailId);if(v){const show=revealed(s,v);body=button('back-bag',`${icon('back')} 返回种植`,'link-button')+`<div class="detail-art">${show?art(v.artKey):sealed()}<div><h3>${esc(show?v.name:'一颗灵感新种子')}</h3><p>${show?esc(v.gesture??'轻碰它，叶子会回应你。'):'模样留到成熟时揭晓。'}<br>长大 ${durationLabel(v.growMs)} · 整株售 ${coin(v.salePrice)} 金币</p></div></div><p class="detail-description">${show?esc(v.description):'这一颗种子已经保存好了。种下以后，再认识它的小脾气。'}</p><p class="author-line">${v.kind==='basic'?'原生种':`原作者 ${esc(v.authorName)}`}${v.parentId?`<br>改造自 ${esc(getVariety(s,v.parentId)?.name??'另一颗种子')} · 原作 ${esc(v.parentAuthorName??getVariety(s,v.parentId)?.authorName??'花园居民')}`:v.kind==='creative'?' · 从零发明':''}</p><div class="button-row">${button('choose-seed',`${icon('seed')}种下 ×${s.inventory[v.id]??0}`,'primary',`data-id="${esc(v.id)}" ${(s.inventory[v.id]??0)<=0?'disabled':''}`)}${button('remix',`${icon('crystal')}改造`,'secondary',`data-id="${esc(v.id)}"`)}</div>${canBuySeed(s,v.id)?button('buy-seed',`再买一颗 · ${coin(v.seedPrice)}`,'link-button full',`data-id="${esc(v.id)}" ${s.coins<v.seedPrice?'disabled':''}`):'<p class="help-note">串门所得种子保留原作者，想再带一颗，明天去它的示范花园吧。</p>'}`;}}
 else if(tab==='seeds'){
  body+=seedList(s,u);
 }else if(tab==='plants'){
  const packed=s.plantBag??[];body+=packed.length?`<div class="item-grid">${packed.map(p=>{const v=getVariety(s,p.varietyId),mature=isMature(p,Date.now());return `<div class="item-card">${mature?art(v.artKey):sealed()}<b>${esc(mature?v.name:'正在长大的植物')}</b><small>${mature?'原来那一株 · 已成熟':'成长时间继续走'}</small>${button('restore-plant','摆回花园','card-buy',`data-id="${esc(p.id)}"`)}${button('sell-packed-plant',`卖出 ${coin('+'+v.salePrice)}`,'link-button seed-detail',`data-id="${esc(p.id)}" ${!mature?'disabled':''}`)}</div>`;}).join('')}</div>`:'<div class="empty">这里收着整株植物。<br>轻碰自己花园的成熟植物，就能收进来。</div>';
 }else{
  const known=knownVarieties(s);body+=`<div class="item-grid">${known.map(v=>button('detail',`${revealed(s,v)?art(v.artKey):sealed()}<b>${esc(revealed(s,v)?v.name:'灵感新种子')}</b><small>${v.kind==='basic'?'原生种':`原作 ${esc(v.authorName)}`}</small>`,'item-card collection-card',`data-id="${esc(v.id)}"`)).join('')}</div><p class="help-note">收好 ${known.length} 个已认识的品种。每颗种子，都带着自己的来处。</p>`;
 }
 return wrap('我的种植',body,'',tab==='seeds'&&!u.detailId?creationRail('panel-create','创造新种子'):'');
}
function creationPhotoControl(u,disabled=false){const p=u.creationPhoto??{};return `<div class="creation-photo"><div class="creation-photo-row">${p.url?`<img src="${esc(p.url)}" alt="所选照片预览" class="creation-photo-thumb">`:''}${button('creation-photo-add',p.url?'更换照片':'＋ 添加照片','creation-photo-button',disabled?'disabled':'')}${p.url||p.loading?button('creation-photo-remove','移除照片','creation-photo-remove'):''}${p.loading?'<span class="creation-photo-status" role="status">读取中…</span>':''}</div>${p.url?'<p class="creation-photo-note">仅本地预览 · 暂未接图片生成</p>':''}${p.error?`<p class="creation-photo-error" role="status">${esc(p.error)}</p>`:''}</div>`;}
function createPanel(s,u){
 const c=u.creation,remix=c.path==='remix',parent=remix?getVariety(s,c.parentId):null,options=remix?compatibleRemixSamples(s,c.parentId):CREATIVE_SAMPLES;
 const noDirections=remix&&!options.length,reuse=c.reuseId?getVariety(s,c.reuseId):null;
 const hint=remix?(options[0]?.name??'这个品种暂无更多离线改造方向'):'会漂浮的云朵灯';
 const body=`${remix?`<p class="creation-parent">改造 · <b>${esc(parent?.name??'这颗种子')}</b><small>保留原来的植物家族与来源</small></p>`:'<p class="creation-prompt">想让什么奇妙的小居民住进花园？</p>'}<form id="idea-form" class="idea-form simple-idea"><label class="visually-hidden" for="idea-input">写下${remix?'改造':'创造'}想法</label><input id="idea-input" name="idea" maxlength="80" autocomplete="off" placeholder="比如：${esc(hint)}" value="${esc(c.idea)}" ${noDirections?'disabled':''}>${button('idea-dice','🎲','idea-dice',`aria-label="摇一个植物灵感" ${noDirections?'disabled':''}`)}</form>${creationPhotoControl(u,noDirections)}<p class="creation-feedback" role="status">${esc(c.error??'')}</p>${reuse?'<p class="reuse-note">这个离线样例你已经有了，可以直接再种。<br>保留已有品种原来的作者与来源。</p>':''}${noDirections?'<p class="help-note">这个品种暂无更多离线改造方向。</p>':''}<p class="offline-note">离线样例 · 非实时 AI · 不支持的想法不扣水晶</p>`;
 const footer=reuse?`${button('reuse-seed',`${icon('seed')} ${(s.inventory[reuse.id]??0)>0?'直接再种':`再买一颗 · ${coin(reuse.seedPrice)} 金币`}`,'primary full',`data-id="${esc(reuse.id)}" ${(s.inventory[reuse.id]??0)<=0&&s.coins<reuse.seedPrice?'disabled':''}`)}<p class="sample-cost">已有样例 · 不用水晶</p>`:`${button('confirm-create',`${icon('crystal')} ${remix?'改造':'创造'}一颗新种子 · 1 水晶`,'primary purple full',`${noDirections?'disabled':''}`)}<p class="sample-cost">剩余 ${s.crystals} 颗 · 成功才扣除</p>`;
 return `${header(remix?'改造种子':'创造新种子','1 水晶')}<div class="tray-content">${body}</div><footer class="tray-footer">${footer}</footer>`;
}
function legacyBuildings(s){const old=s.buildingBag??[];return old.length?`<h3 class="collection-heading">待安置建筑</h3><p class="help-note">旧版收好的建筑可免费摆回一次；摆回后只能付费搬迁或拆除。</p><div class="item-grid">${old.map(b=>{const p=getBlueprint(s,b.blueprintId);return `<div class="item-card">${art(p.artKey)}<b>${esc(p.name)}</b>${button('restore-building','免费安置','card-buy',`data-id="${esc(b.id)}"`)}</div>`;}).join('')}</div>`:'';}
function recoveryPanel(s,u){if(!legacyRecoveryEligible(s,Math.max(Date.now(),s.lastSeenAt)))return '';return `<section class="legacy-recovery"><h3>旧版布局恢复</h3><p class="help-note">新的房屋占地规则让旧岛没有落脚空间。可自愿移除一座已建好的小屋；永久图纸保留，不返金币，也不赠地。</p>${s.buildings.filter(b=>isBuilt(b,Math.max(Date.now(),s.lastSeenAt))).map(b=>u.recoveryId===b.id?`<p class="help-note">确认移除${esc(getBlueprint(s,b.blueprintId).name)}？这一座会离开，永久图纸保留；本次免拆除费。</p><div class="button-row">${button('cancel-legacy-recovery','暂不恢复','secondary')}${button('confirm-legacy-recovery','恢复落脚空间（本次免拆除费）','primary',`data-id="${esc(b.id)}"`)}</div>`:button('legacy-recovery',`选择${esc(getBlueprint(s,b.blueprintId).name)}恢复落脚空间`,'secondary full',`data-id="${esc(b.id)}"`)).join('')}</section>`;}
function landPaletteControls(s,u){
 if(u.visitId)return '';
 const selected=landPalette(s.settings.landPalette).id;
 return `<section class="land-palette-controls" aria-label="整岛地块色调"><h3>整岛地块色调 <small>免费 · 只改变自己的土地</small></h3><div class="land-palette-swatches">${LAND_PALETTES.map(p=>button('land-palette',`<i aria-hidden="true" style="--swatch-land:${p.land};--swatch-side:${p.side}"></i><span>${esc(p.name)}</span>`,'land-swatch',`data-id="${p.id}" aria-pressed="${p.id===selected}" aria-label="${esc(p.name)}地块色调"`)).join('')}</div></section>`;
}
function buildPanel(s,u){const blueprints=Object.keys(s.blueprints??{}).map(id=>getBlueprint(s,id)).filter(p=>p&&isActiveBuildingSample(p.sampleId));return wrap('布置我的小岛',`<p class="panel-subtitle">把小岛拼成喜欢的形状。<b>只有土地可以种植</b>，边饰不占种植位置。</p><div class="build-grid">${Object.values(BUILDINGS).map(b=>button('choose-build',`${art(b.id)}<b>${b.name}</b><small>${coin(b.price)}</small>`,'build-card',`data-id="${b.id}" ${s.coins<b.price?'disabled':''} aria-label="建造${b.name}，${b.price}金币"`)).join('')}</div><p class="help-note">离线建筑样例 · 图纸永久保留，建造每座60金币。</p>${blueprints.length?`<h3 class="collection-heading">我的永久图纸</h3><div class="item-grid">${blueprints.map(p=>`<div class="item-card">${art(p.artKey)}<b>${esc(p.name)}</b><small>${p.footprint.join('×')} · 图纸永久保留</small>${button('choose-blueprint',compactPrice('建造',60),'card-buy price-action',`data-id="${esc(p.id)}" ${s.coins<60?'disabled':''} aria-label="建造${esc(p.name)}，60金币"`)}</div>`).join('')}</div>`:''}${landPaletteControls(s,u)}${legacyBuildings(s)}${recoveryPanel(s,u)}<div class="button-row">${button('edit-build',`${icon('move')}移动 / 收回`,'secondary full')}</div><p class="help-note">地块贴着小岛摆放；栅栏和矮墙沿地块边缘摆放。它们是可以跨过的低矮装饰，不挡走路。<br>先收好成熟植物，或搬迁 / 拆除建筑，再移动土地；地块收回会返还部分金币，地块移动免费。<br>建筑搬迁20金币，拆除50金币，不会收进背包。</p>`,'',creationRail('blueprint-create','创造建筑图纸'));}
function blueprintPanel(s,u){
 const c=u.blueprintCreation??{},parent=c.parentId?getBlueprint(s,c.parentId):null,reuse=c.reuseId?getBlueprint(s,c.reuseId):null;
 const hint=parent?.sampleId==='calico_reading_den'?'露营狗狗工坊':'一间猫咪书屋';
 return `${header(parent?'改造建筑图纸':'创造建筑图纸','1 水晶')}<div class="tray-content">${parent?`<p class="creation-parent">改造自 ${esc(parent.name)}<small>原作 ${esc(parent.authorName)} · 保留来源</small></p>`:'<p class="creation-prompt">想让哪段小回忆，变成一座小屋？</p>'}<form id="building-idea-form" class="idea-form simple-idea"><label for="building-idea-input" class="visually-hidden">建筑想法</label><input id="building-idea-input" name="idea" maxlength="80" autocomplete="off" placeholder="比如：${hint}" value="${esc(c.idea??'')}">${button('roll-building-idea','🎲','idea-dice','aria-label="摇一个建筑灵感"')}</form>${creationPhotoControl(u)}<p class="creation-feedback" role="status">${esc(c.error??'')}</p>${reuse?'<p class="reuse-note">已有这张永久图纸，直接用金币建造就好。</p>':''}<p class="offline-note">${ACTIVE_BUILDING_SAMPLES.length} 个离线样例 · 暂未接实时生成</p></div><footer class="tray-footer">${reuse?button('choose-blueprint',`建造 ${esc(reuse.name)} · ${coin(60)} 金币`,'primary full',`data-id="${esc(reuse.id)}" ${s.coins<60?'disabled':''}`):button('confirm-blueprint',`${icon('crystal')}创造永久图纸 · 1 水晶`,'primary purple full')}<p class="sample-cost">1 水晶创造永久图纸 · 建造一座 ${coin(60)} 金币<br>剩余 ${s.crystals} 水晶 · ${coin(s.coins)} 金币 · 不支持不扣除</p></footer>`;
}
// Display-only NPC sale-income bands adapted from the previous manor demo.
// No player balances, transactions, or storage enter this deterministic view.
export function mockVisitRanking(period='today',now=Date.now(),owner=null){
 const day=86400000,offset=8*3600000,dayStart=Math.floor((now+offset)/day)*day-offset;
 const weekStart=dayStart-((new Date(dayStart+offset).getUTCDay()+6)%7)*day;
 const weekly=period==='week',key=weekly?'week':'day',start=weekly?weekStart:dayStart;
 const tiers={'demo-frog':[420,160],'demo-kelly':[1250,400],'demo-bear':[3600,900],'demo-lx':[5200,1200]};
 const rows=[...DEMO_GARDENS,...(owner?[{id:'my-inspiration-garden',authorId:`self:${owner.uid}`,authorName:owner.profileName,avatarKey:PLAYER_AVATAR,name:'我的花园',subtitle:'模拟展示',theme:'self',self:true}]:[])];
 return rows.map(g=>{
  const [base,spread]=g.self?[720,240]:tiers[g.authorId];let hash=2166136261;
  for(const char of `${g.authorId}:${key}:${start}`)hash=Math.imul(hash^char.charCodeAt(0),16777619);
  return {...g,income:base*(weekly?5:1)+(hash>>>0)%(spread*(weekly?3:1))};
 }).sort((a,b)=>b.income-a.income||(a.authorId<b.authorId?-1:a.authorId>b.authorId?1:0)).map((g,i)=>({...g,rank:i+1}));
}
function visitPanel(s,u,avatars){
 const period=u.visitPeriod==='week'?'week':'today',label=period==='week'?'本周':'今日';
 const cards=mockVisitRanking(period,Date.now(),s).map(g=>{const own=!!g.self,name=own&&g.authorName==='我'?(avatars?.[g.avatarKey]?.name??'花园主人'):(g.hostName??g.authorName),atHome=own&&!u.visitId;
  return button(own?'go-home':'visit-garden',`<i class="friend-rank" aria-label="第 ${g.rank} 名">${g.rank}</i>${avatarPortrait(g.avatarKey,name)}<span class="friend-identity"><b${own?' class="self-name"':''}>${own?`<span>${esc(name)}</span><i class="self-badge">我</i>`:esc(name)}</b><small>${esc(own?g.name:g.progression?`示范 Lv.${g.progression.level} · ${g.progression.tierLabel} · ${g.tiles.length}格`:g.name)}</small><em>${esc(g.subtitle)}</em></span><span class="friend-income">${coin(g.income.toLocaleString('en-US'))}<small>${own?(atHome?'我的花园':'回到我的花园'):`串门 ${icon('chevron-right','visit-chevron')}`}</small></span>`,`garden-card ranked-garden ${g.theme}${own?' self-garden':''}`,`data-id="${g.id}" aria-label="${own?'我的花园':`去${esc(g.hostName??g.authorName)}的${esc(g.name)}串门`}，${label}模拟收益${g.income}金币" ${atHome?'disabled aria-current="location"':''}`);
 }).join('');
 return wrap('去示范花园串门',`<div class="ranking-heading"><span><b>模拟收益排行</b><small>示例数据 · ${label}卖出植物所得</small></span><div class="ranking-period" aria-label="排行周期">${[['today','今日'],['week','本周']].map(([id,text])=>button(`visit-period-${id}`,text,period===id?'active':'',`aria-pressed="${period===id}"`)).join('')}</div></div><p class="ranking-note">北京时间 · ${period==='week'?'周一开始':'每天零点更新'} · 不计入金币余额</p><div class="garden-cards">${cards}</div><p class="help-note">本地示范花园 · 非实时玩家。和植物玩一下，带一颗种子回家。<br>同一品种每天 1 颗（北京时间），保留原作者。</p>`);
}
function profilePanel(s,avatars,wardrobe){const outfits=wardrobe?.outfits??{original:{name:'白衫日常',description:'熟悉的白衫与黄色墨镜'}};return wrap('苏贝壳的衣橱',`<p class="panel-subtitle">今天，想穿成什么心情？</p><div class="outfit-grid">${Object.entries(outfits).map(([id,a])=>button('choose-outfit',`<canvas class="outfit-portrait" data-outfit-portrait="${esc(id)}" role="img" aria-label="苏贝壳 · ${esc(a.name)}"></canvas><span class="outfit-load-status" data-outfit-status aria-live="polite"></span><b>${esc(a.name)}</b><small>${esc(a.description??'')}</small>`,'outfit-choice '+(playerOutfit(s)===id?'active':''),`data-id="${esc(id)}" aria-pressed="${playerOutfit(s)===id}"`)).join('')}</div>${button('panel-info',`${icon('info')} 关于这个小花园`,'link-button full')}`);}
function infoPanel(){return wrap('关于灵感花园',`<div class="info-copy"><h3>先种一点，再认识一点</h3><p>买种子 → 轻点土地种下 → 等待成熟 → 轻碰植物玩一下。成熟植物可以留下玩、收进背包再摆回，也能整株卖掉换金币。轻摇成熟植物，每品种每天一颗种子。金币买种子、扩建小岛；自己的建筑图纸每座用60金币建造。建筑搬迁20金币、拆除50金币，不会收进背包。</p><h3>一颗水晶，一次新的尝试</h3><p>水晶创造新品种或永久建筑图纸，可以改造已有作品，也能从零发明。这个 Demo 使用离线设计样例，不连接实时 AI。取消预览不扣水晶，只有确认成功才扣 1 颗。</p><h3>本地，安静，不用登录</h3><p>进度只保存在当前浏览器。四座示范花园不是实时玩家，也没有在线交易。这里没有付费、结账或后台生成；模拟补充水晶不会收取任何费用。</p><h3>熟悉的角色，新的开始</h3><p>保留上一版十二位角色的身份特征，统一成手绘 2D 小模样。这是独立的新 Demo，使用全新的本地存档，不会读取或更改旧花园。</p><p>拖动画面移动视角，双指或右侧按钮缩放。声音可以随时关闭；静音也能玩全部互动。</p></div>`);}
function crystalsPanel(s){const claimed=s.lastDailyClaim===dayKey(Date.now());return wrap('灵感水晶小补给',`<div class="crystal-hero">${icon('crystal')}<strong>${s.crystals}</strong><span>颗灵感水晶</span></div><div class="grant-row"><span><b>每日一点灵感 · +2</b><small>北京时间每天可领一次</small></span>${button('daily-claim',claimed?'今天已领取':'领取','',''+(claimed?'disabled':''))}</div><div class="grant-row"><span><b>演示补充 · +3</b><small>模拟购买概念，无结账、无真实收费</small></span>${button('demo-crystals','模拟补充')}</div><p class="help-note">一颗水晶确认创造一个新品种。以后再买同种种子只用金币，不会重复收取水晶。卖植物不会返还水晶。</p>`);}
function giftPanel(s,u){const session=u.friendSession;if(!session?.ready)return '';const tab=u.giftTab==='plants'?'plants':'seeds',selection=u.giftSelection,time=Math.max(Date.now(),s.lastSeenAt);let items='';if(tab==='seeds')items=Object.entries(s.inventory).filter(([,n])=>n>0).map(([id,n])=>{const v=getVariety(s,id),show=revealed(s,v);return button('gift-select-seed',`${show?art(v.artKey):sealed()}<b>${esc(show?v.name:'灵感新种子')}</b><small>×${n} · 原作 ${esc(v.authorName)}</small>`,'item-card gift-choice'+(selection?.kind==='seed'&&selection.id===id?' active':''),`data-id="${esc(id)}"`);}).join('');else items=(s.plantBag??[]).map(p=>{const v=getVariety(s,p.varietyId),mature=isMature(p,time);return button('gift-select-plant',`${mature?art(v.artKey):sealed()}<b>${esc(mature?v.name:'正在长大的植物')}</b><small>${mature?'送出原来这一株':'成熟后才可赠送'}</small>`,'item-card gift-choice'+(selection?.kind==='plant'&&selection.id===p.id?' active':''),`data-id="${esc(p.id)}" ${!mature?'disabled':''}`);}).join('');const selected=selection?.kind==='seed'?getVariety(s,selection.id):getVariety(s,(s.plantBag??[]).find(p=>p.id===selection?.id)?.varietyId);return wrap(`送给 ${esc(session.name)}`,`<p class="gift-disclosure">本地赠送演示：扣除本机库存，不会送达或通知真实好友。</p><div class="bag-tabs">${button('gift-tab-seeds','种子',tab==='seeds'?'active':'')}${button('gift-tab-plants','收获',tab==='plants'?'active':'')}</div><div class="item-grid">${items||'<p class="empty">这里暂时没有可送的物品。</p>'}</div>`,'',`<footer class="tray-footer"><p class="sample-cost">${selected?`送给 ${esc(session.name)} · ${esc(revealed(s,selected)?selected.name:'灵感新种子')} ×1`:'先选择一份礼物'}</p>${button('confirm-gift',selection?.kind==='plant'?'送出这一株':'送出 1 颗','primary full',selection&&selected?'':'disabled')}</footer>`);}
export function renderPhotoContent(u){const p=u.photoState??{},date=photoMemorialDate(p.openedAt);return `<p class="offline-note">苏贝壳 × ${esc(u.friendSession?.name)}</p>${date?`<time class="photo-memorial-date" datetime="${date.key}">${date.label}</time>`:''}${p.status==='ready'?`<img class="offline-selfie" src="${esc(p.previewURL)}" alt="苏贝壳和${esc(u.friendSession?.name)}的离线插画合影样片">`:p.status==='error'?`<div class="photo-loading" role="status">${esc(p.error)}</div>`:'<div class="photo-loading" role="status">正在打开离线合影样片…</div>'}`;}
export const photoStatus=u=>u.photoState?.status==='ready'?'可长按图片保存，也可保存原始 PNG。':u.photoState?.status==='error'?'样片暂未载入，可重试；不会花费水晶。':'正在载入这一张样片，不会花费水晶。';
function photoPanel(s,u){const ready=u.photoState?.status==='ready',error=u.photoState?.status==='error';return wrap('合影样片',`<div id="photo-view">${renderPhotoContent(u)}</div>`,'',`<footer class="tray-footer photo-footer"><p class="sample-cost" id="photo-status">${photoStatus(u)}</p><div class="button-row">${button('photo-retry','重试','secondary',`id="photo-retry" ${error?'':'hidden'}`)}${button('photo-download','保存 PNG','primary full',`id="photo-download" ${ready?'':'disabled'}`)}</div></footer>`);}
function invitePanel(){return wrap('邀请好友',`<div class="invite-card"><div class="invite-illustration" aria-hidden="true">${avatarPortrait(PLAYER_AVATAR,'苏贝壳')}<span class="invite-growing">${icon('seed')}</span><span class="invite-friend">${icon('invite')}</span></div><h3>贝壳的花园</h3><p>邀请朋友，一起种点喜欢的东西</p><div class="invite-card-note">一人一个小想法，慢慢长成我们的花园。</div></div>`, '', `<footer class="tray-footer invite-footer">${button('invite-share',`${icon('invite')} 分享邀请`,'primary full')}${button('invite-copy','复制邀请链接','invite-copy')}</footer>`);}
export function renderPanel(s,u,avatars,wardrobe=null){
 switch(u.panel){case 'invite':return invitePanel();case 'gift':return giftPanel(s,u);case 'photo':return photoPanel(s,u);case 'shop':return bagPanel(s,{...u,bagTab:'seeds'});case 'bag':return bagPanel(s,u);case 'create':return createPanel(s,u);case 'build':return buildPanel(s,u);case 'blueprint-create':return blueprintPanel(s,u);case 'visit':return visitPanel(s,u,avatars);case 'profile':return profilePanel(s,avatars,wardrobe);case 'info':return infoPanel();case 'crystals':return crystalsPanel(s);default:return '';}
}
export function renderContext(s,u,world){
 const selected=u.selection;if(!selected)return '';const time=Math.max(Date.now(),s.lastSeenAt);
 const close=button('clear-selection',icon('close'),'context-close','aria-label="取消选择"');
 if(selected.kind==='exhibit'){
  const e=world.exhibits?.find(e=>e.id===selected.id);if(!e)return '';const blueprint=e.blueprintId?getBlueprint(u.visitId?{blueprints:{}}:s,e.blueprintId):null;if(!isBuilt(e,time))return close+workContext(e,time,e.displayName??e.name??'小屋');
  const sourceType=e.sourceType??blueprint?.sourceType,sourceFrameId=e.sourceFrameId??blueprint?.sourceFrameId,hasSourcePhoto=!!sourceFrameId&&!['hobby','illustration'].includes(sourceType);
  const sourceVisual=hasSourcePhoto?`<canvas class="source-photo" data-source="${esc(sourceFrameId)}" aria-label="${esc(sourceType==='user-provided-photo'?'我的猫咪原照片':sourceType==='memory'?'纪念物品照片':'灵感相册照片')}"></canvas>`:art(e.artKey??blueprint?.artKey,'source-building-art');
  const sourceLabel=sourceType==='user-provided-photo'?`我的猫咪 · ${esc(e.sourceDateLabel??blueprint?.sourceDateLabel??'提供于')} ${esc(e.sourceDate??blueprint?.sourceDate??'2026-10-26')}`:sourceType==='memory'?`灵感相册 · ${esc(e.sourceDisclosure??blueprint?.sourceDisclosure??'纪念手记')}`:hasSourcePhoto?'灵感相册':sourceType==='hobby'?'兴趣灵感 · 离线创作样例':sourceType==='illustration'?'插画灵感 · 离线创作样例':'灵感创作 · 离线样例';
  return close+`<div class="exhibit-context">${sourceVisual}<div><h3>${esc(e.displayName??e.label??'相册小屋')}</h3><p>${esc(blueprint?.gesture??e.gesture??exhibitHint(e.interaction))}</p><small>${sourceLabel}</small></div></div><p class="source-story">${esc(e.sourceStory??blueprint?.sourceStory??(hasSourcePhoto?'照片里的小细节，变成了这座会回应你的建筑。':'把自己的想法，变成一座会回应的小屋。'))}</p>${e.personal?(u.demolishId===e.id?`<p class="demolition-warning">拆除这座小屋需要${DEMOLITION_PRICE}金币，永久图纸会保留。</p><div class="context-actions compact-actions">${button('confirm-demolition',`确认拆除 · ${coin(DEMOLITION_PRICE)} 金币${s.coins<DEMOLITION_PRICE?` · 还差 ${DEMOLITION_PRICE-s.coins} 金币`:``}`,'danger',`data-id="${esc(e.id)}" ${s.coins<DEMOLITION_PRICE?'disabled':''}`)}${button('cancel-demolition','取消','secondary')}</div>`:`<div class="context-actions compact-actions">${button('relocate-building',`搬迁 · ${coin(RELOCATION_PRICE)} 金币${s.coins<RELOCATION_PRICE?` · 还差 ${RELOCATION_PRICE-s.coins} 金币`:``}`,'secondary',`data-id="${esc(e.id)}" ${s.coins<RELOCATION_PRICE?'disabled':''}`)}${button('demolish-building',`拆除 · ${coin(DEMOLITION_PRICE)} 金币${s.coins<DEMOLITION_PRICE?` · 还差 ${DEMOLITION_PRICE-s.coins} 金币`:``}`,'secondary',`data-id="${esc(e.id)}" ${s.coins<DEMOLITION_PRICE?'disabled':''}`)}</div>`)+(s.coins<DEMOLITION_PRICE?'<p class="help-note">金币不足时，可以双击金币余额补充100演示金币。</p>':''):''}${e.blueprintId?`<p class="context-detail">原作 ${esc(e.authorName??blueprint?.authorName??'示范花园')}${blueprint?.parentId?` · 改造自 ${esc(blueprint.parentAuthorName)}`:''} ${button('remix-building','改造','link-button',`data-id="${esc(e.blueprintId)}"`)}</p>`:''}`;
 }
 if(selected.kind==='resident'){const session=u.friendSession;if(!session||session.residentId!==selected.id||session.gardenId!==u.visitId)return '';return close+`<div class="context-head">${avatarPortrait((world.residents??[]).find(r=>r.id===session.residentId)?.avatarKey??DEMO_GARDENS.find(g=>g.id===u.visitId)?.avatarKey,session.name)}<div><h3>${esc(session.name)}</h3><p>${session.ready?'示范朋友 · 一起留个小纪念':'正走过去，到了再聊'}</p></div></div>${session.ready?`<div class="context-actions">${button('friend-photo','合影','primary')}${button('friend-gift','送东西','secondary')}</div>`:''}${u.giftThanks?`<p class="context-detail">${esc(u.giftThanks)}</p>`:''}`;}
 if(selected.kind==='plant'){

  const plant=world.plants.find(p=>p.id===selected.id),v=plant&&(u.visitId?allCatalogueVarieties()[plant.varietyId]:getVariety(s,plant.varietyId));if(!plant||!v)return '';
  const mature=isMature(plant,time),demo=!!u.visitId,remaining=Math.max(1,Math.ceil((plant.readyAt-time)/1000));
  const countdown=demo?`再等 ${durationLabel(remaining*1000)}`:`<button type="button" class="growth-countdown" data-growth-plant="${esc(plant.id)}" data-tile-id="${esc(plant.tileId)}" data-variety-id="${esc(plant.varietyId)}" data-planted-at="${plant.plantedAt}" data-ready-at="${plant.readyAt}" title="双击倒计时，演示立即成熟" aria-label="再等 ${durationLabel(remaining*1000)}，双击倒计时，演示立即成熟">再等 ${durationLabel(remaining*1000)}</button>`;
  const interacted=s.demoInteractions[`${u.visitId}:${plant.id}`]===dayKey(Date.now()),claimed=s.claims[v.id]===dayKey(Date.now());
  return close+`<div class="context-head">${mature?art(v.artKey):sealed()}<div><h3>${esc(mature?v.name:'正在长大的小居民')}</h3><p>${mature?esc(controlHint(v.interaction)):`${countdown} · 让它在花园里慢慢长大`}</p></div></div><div class="context-actions compact-actions">${!demo&&mature?button('pack-plant','收进背包','secondary',`data-id="${esc(plant.id)}"`):''}${button('shake-seed',claimed?'今天已摇过':'摇出种子','secondary',`data-id="${esc(plant.id)}" ${!mature||claimed||(demo&&!interacted)?'disabled':''}`)}${!demo?button('sell-plant',`卖出 ${coin('+'+v.salePrice)}`,'secondary',`data-id="${esc(plant.id)}" ${!mature?'disabled':''}`):''}</div><p class="context-detail">${v.kind==='basic'?'花园原生种':`原作 ${esc(v.authorName)}`}${footprintOf(v)[0]===2?' · 占地 2×2':''}${(!demo||(Object.hasOwn(s.varieties,v.id)&&sameVariety(s.varieties[v.id],v)))?` ${button('remix','改造','link-button',`data-id="${esc(v.id)}"`)}`:' · 每品种每天一颗'}</p>${!mature?button('panel-visit','去朋友花园看看','link-button full'):''}`;
 }
 if(selected.kind==='tile'){
  const tile=world.tiles.find(t=>t.id===selected.id);if(!tile)return '';if(!isBuilt(tile,time))return close+workContext(tile,time,BUILDINGS[tile.kind].name);const pendingEdge=(world.edges??[]).some(e=>e.tileId===tile.id&&!isBuilt(e,time));const occupied=pendingEdge||plantAtTile(world,tile.id,s.varieties)||buildingAtTile(world,tile.id);
  if(u.editing)return close+`<div class="context-head"><div><h3>${BUILDINGS[tile.kind].name}</h3><p>${tile.kind==='land'?'先收好成熟植物，或搬迁 / 拆除这里的建筑，再搬走土地。':'木平台不能种植，适合留一条散步的小路。'}</p></div></div><div class="context-actions">${button('move-selected',`${icon('move')}移动`,'primary',occupied?'disabled':'')}${button('reclaim-selected',`${icon('coin')}收回 +${reclaimRefund(s,tile.id)}`,'secondary',occupied?'disabled':'')}</div>`;
  return close+`<div class="context-head"><div><h3>${tile.kind==='land'?'给这里种点什么？':'一块暖暖的木平台'}</h3><p>${tile.kind==='land'?'种一颗种子，认识一位小居民。':'平台不长植物，留给散步与想象。'}</p></div></div><div class="context-actions">${tile.kind==='land'?button('plant-here',`${icon('seed')}选一颗种子`,'primary'):button('panel-build',`${icon('hammer')}继续布置`,'primary')}${button(tile.kind==='land'&&s.plantedCount===0?'panel-visit':'clear-selection',tile.kind==='land'&&s.plantedCount===0?'先去朋友家':'随便逛逛','secondary')}</div>`;
 }
 if(selected.kind==='edge'){
  const edge=world.edges.find(e=>e.id===selected.id);if(!edge)return '';if(!isBuilt(edge,time))return close+workContext(edge,time,BUILDINGS[edge.kind].name);
  return close+`<div class="context-head"><div><h3>${BUILDINGS[edge.kind].name}</h3><p>低矮边饰，不占种植空间，也不阻挡走路。</p></div></div><div class="context-actions">${button('move-selected',`${icon('move')}移动`,'primary')}${button('reclaim-selected',`${icon('coin')}收回 +${BUILDINGS[edge.kind].refund}`,'secondary')}</div>`;
 }
 return '';
}
export function renderMode(s,u){
 if(!u.mode)return '';const m=u.mode;let label='',hint='',price=null;
 if(['construct-building','restore-building','relocate-building'].includes(m.kind)){label=m.kind==='construct-building'?m.name:m.kind==='relocate-building'?`搬迁 ${m.name}`:`摆回旧建筑 ${m.name} · 免费`;price=m.kind==='construct-building'?60:m.kind==='relocate-building'?RELOCATION_PRICE:null;hint=m.kind==='relocate-building'?'点选有效新址才扣费 · 可取消':`连续${(getBlueprint(s,m.blueprintId)?.footprint??[2,2]).join('×')}空位 · 土地/平台可混合`;}
 else if(m.kind==='plant'||m.kind==='restore'){const p=m.kind==='restore'?(s.plantBag??[]).find(p=>p.id===m.plantId):null,v=getVariety(s,p?.varietyId??m.varietyId);label=m.kind==='restore'?`摆回 ${v?.name??'植物'}`:`${v&&revealed(s,v)?v.name:'灵感新种子'} ×${s.inventory[m.varietyId]??0}`;hint=footprintOf(v)[0]===2?'需要 2×2 连在一起的空土地':'轻点一块发亮的空土地';}
 else if(m.kind==='edit'){label='布置模式';hint='轻点地块或边饰，移动 / 收回';}
 else if(m.kind==='move-tile'){label='移动地块 · 免费';hint='轻点小岛旁的空位';}
 else if(m.kind==='move-edge'){label='移动边饰 · 免费';hint='轻点另一条地块边缘';}
 else{label=BUILDINGS[m.kind].name;price=BUILDINGS[m.kind].price;hint=['fence','wall'].includes(m.kind)?(m.edgePreview?.armed?'再点同一条边，确认建造':'轻点选边，再点同一处建造'):'轻点小岛旁的 + 位置';}
 return `<span>${icon(['construct-building','restore-building','relocate-building'].includes(m.kind)?'hammer':['plant','restore'].includes(m.kind)?'seed':m.kind==='edit'||m.kind.startsWith('move')?'move':m.kind)}<span style="display:block">${esc(label)}${price!==null?` · ${coin(price)} 金币`:''}<small>${hint}</small></span></span>${button('cancel-mode',m.kind==='relocate-building'?'取消搬迁':'完成')}`;
}
